  savedCheckpoint(story:SavedStoryRecord){const status=this.savedLifecycle(story);if(status==='ARCHIVED')return 'Archived';if(status==='APPROVED'&&this.savedBuildForStory(story))return 'Production prompt';if(status==='APPROVED')return 'Prompt step';if(this.savedBuildRecords.some(row=>String((row.sourceRequest?.context||row.payload?.sourceRequest?.context||{}).sourceStoryRecordId||'')===String(story.recordId)))return 'Prompt draft · review lineage';return status==='DRAFT'?'Story draft':'Story review';}
  private savedBuildForStory(story:SavedStoryRecord){const approval=this.savedApprovalRecordsFor(story).find(row=>this.approvalMatchesCandidate(story,row));if(!approval)return null;const candidateId=String(approval.candidateId||approval.payload?.candidateId);const revisionId=String(approval.revisionId||approval.payload?.revisionId);return this.savedBuildRecords.find(row=>{const context=row.sourceRequest?.context||row.payload?.sourceRequest?.context||{};const result=row.result||row.payload?.result||{};return Boolean(result.prompt)&&String(context.sourceStoryRecordId||'')===String(story.recordId)&&String(context.storyRevisionId||'')===revisionId&&revisionId.startsWith(`${candidateId}-revision-`);})||null;}
