  savedApprovalFor(story:SavedStoryRecord){const matches=this.savedApprovalRecordsFor(story);if(!matches.length)return null;const approval=matches.find(item=>this.approvalMatchesCandidate(story,item))||matches[0];const approvedCandidate=approval.candidateId||approval.payload?.candidateId;const approvedRevision=approval.revisionId||approval.payload?.revisionId;return {...approval,approvedCandidateId:approvedCandidate,approvedRevisionId:approvedRevision};}
