  private runStoryRole(){this.busy=true;this.error='';this.http.post<any>('/api/v1/intelligence/workflow/creative-role',{role:'STORY',text:this.idea.trim(),maxCostUsd:this.budget,context:{constraints:this.constraints,mainCharacter:this.selectedCharacterName||null,preferences:this.preferences,storyGenerationMode:this.storyMode,lockedRequirements:this.lockedRequirements,permittedVariation:this.storyMode==='IMPROVE_EXISTING_STORY'?'Refine clarity, staging, execution risk and presentation':'Explore opening, strategy, obstacle, escalation, reveal and ending structure',workspacePath:this.workspacePath,requestedAlternativeCount:this.candidateCount,targetConfiguration:{aspectRatio:this.aspectRatio,duration:this.duration,selectedGenerator:this.targetGenerator,contentProfile:this.profile,mainCharacter:this.selectedCharacterName||null},lessonContext:{contentProfile:this.profile,modelVersion:'',duration:this.duration,generator:this.targetGenerator,settings:{aspectRatio:this.aspectRatio,mode:'image2video',resolution:'480p'}}}}).subscribe({next:r=>{this.storyRecordId=r.recordId;this.storyQuality=r.result?.storyQuality || null;this.storyReview=null;this.storyReviewStatus='NOT_REVIEWED';this.candidates=(r.result?.alternatives||[]).slice(0,this.candidateCount).map((item:any,i:number)=>{const evidence=this.storyQuality?.candidates?.[i] || {};return typeof item==='string'?{candidateId:`${this.storyRecordId}-candidate-${i+1}`,title:`Alternative ${i+1}`,text:item,structuralEvidence:evidence.structuralEvidence,preflight:evidence.preflight}:{candidateId:(item.candidateId && item.candidateId !== 'None' && item.candidateId !== 'null') ? item.candidateId : `${this.storyRecordId}-candidate-${i+1}`,title:item.title||`Alternative ${i+1}`,text:item.text||item.description||JSON.stringify(item),structuralEvidence:item.structuralEvidence||evidence.structuralEvidence,preflight:item.preflight||evidence.preflight};});this.stage='STORY';this.storyConsent=false;this.persist();this.done();},error:e=>this.fail(e,'DeepSeek could not generate story ideas.')});}
  selectStory(candidate:StoryCandidate){this.selectedCandidateIdValue=candidate.candidateId;this.selectedStory=candidate.text;this.persist();}
  candidateReview(candidateId:string){return this.storyReview?.candidateReviews?.find((item:any)=>item.candidateId===candidateId) || null;}
  recommendedStoryLabel(){const index=this.recommendedCandidateIndex();return index>=0?`Alternative ${index+1}`:'None';}
  recommendedCandidateIndex(){const id=this.storyReview?.recommendedCandidateId;const direct=this.candidates.findIndex(item=>item.candidateId===id);if(direct>=0)return direct;const match=String(this.storyReview?.recommendationReason||'').match(/candidate\s*(\d+)/i);return match?Number(match[1])-1:-1;}
  isRecommendedCandidate(candidate:StoryCandidate,index:number){return this.recommendedCandidateIndex()===index;}
  reviewFindingsText(value:any){if(typeof value==='string')return value;if(!value||typeof value!=='object')return '';return Object.entries(value).map(([key,item])=>`${key}: ${Array.isArray(item)?item.join(', '):String(item)}`).join(' · ');}
