  private storyFingerprint(value:string){let hash=2166136261;for(let i=0;i<value.length;i++){hash^=value.charCodeAt(i);hash=Math.imul(hash,16777619);}return (hash>>>0).toString(16).padStart(8,'0');}
  onSelectedStoryChange(value:string){this.selectedStory=value;const selected=this.candidates.find(item=>item.candidateId===this.selectedCandidateId);if(this.storyReview && selected && this.reviewedStoryFingerprints[selected.candidateId]!==this.storyFingerprint(value)){this.storyReviewStatus='STALE';}this.persist();}
