  private loadStoryReviewFixture(){this.storyRecordId='LOCAL_MOCK_STORY';this.idea='Mimi and sticky notes';this.title="Mimi's Sticky Note Mystery";this.profile='ABSURD_PHYSICS';this.candidates=[{candidateId:'candidate-1',title:'Alternative 1',text:'Mimi opens the cabinet and the notes follow her to a hidden map.'},{candidateId:'candidate-2',title:'Alternative 2',text:'Mimi shakes the cabinet; existing notes peel away and remain visible as they cover her.'},{candidateId:'candidate-3',title:'Alternative 3',text:'Mimi hides beside the cabinet and discovers the notes are guiding her home.'}];this.selectedCandidateIdValue='candidate-2';this.selectedStory=this.candidates[1].text;this.storyQuality={classification:'PARTIALLY_DISTINCT',summary:'Fixture candidates share the sticky-note premise but differ in progression.',differences:['Alternative 1 vs Alternative 2: different escalation and ending.']};this.reviewBudget=.01;this.reviewConsent=true;this.stage='STORY';}
