  reviewStories(){if(this.fixtureMode){this.fixtureReview();return;}if(this.reviewBudget<=0||!this.reviewConsent||!this.candidates.length)return;this.reviewBusy=true;this.reviewError='';const payload={role:'STORY_REVIEW',text:this.idea.trim(),maxCostUsd:this.reviewBudget,context:{sourceRequestId:this.storyRecordId,sourceFingerprint:this.storyFingerprint(this.idea.trim()),storyGenerationMode:this.storyMode,lockedRequirements:this.lockedRequirements,profile:this.profile,mainCharacter:this.selectedCharacterName||null,targetDuration:this.duration,aspectRatio:this.aspectRatio,reviewPolicyVersion:'story-review-v1',candidates:this.candidates.map(item=>({candidateId:item.candidateId,text:item.text}))}};this.http.post<any>('/api/v1/intelligence/workflow/creative-role',payload).subscribe({next:r=>{if(this.storyReview)this.storyReviewHistory=[...this.storyReviewHistory,this.storyReview];this.storyReview=this.normalizeStoryReview({...r.result, persistedRecordId:r.recordId, persistedAt:r.createdAt || r.result?.createdAt || new Date().toISOString()});this.storyReviewStatus='CURRENT';this.reviewedStoryFingerprints=Object.fromEntries(this.candidates.map(item=>[item.candidateId,this.storyFingerprint(item.text)]));this.reviewConsent=false;this.reviewBusy=false;this.persist();this.changeDetector.markForCheck();},error:e=>{this.reviewError=this.userMessage(String(e?.error?.detail||''),'OpenAI story review could not be completed.');this.reviewBusy=false;this.changeDetector.markForCheck();}});}
  editCandidate(candidate:StoryCandidate){this.selectStory(candidate);}
  refineCandidate(candidate:StoryCandidate){this.selectStory(candidate);this.inputMode='DETAILED_STORY';this.storyMode='IMPROVE_EXISTING_STORY';this.stage='IDEA';this.storyConsent=false;this.error='Refine the selected story, review the locked requirements, and request a bounded improvement.';this.persist();}
  requestMoreDistinct(){if(this.storyMode==='IMPROVE_EXISTING_STORY') return; this.stage='IDEA'; this.error='Generate More Distinct Alternatives will use the existing bounded story budget and preserve the current premise.';}
  readableDimensions(values:any):string{return Array.isArray(values)?values.map((value:string)=>this.readableDifference(value)).join(' · '):'';}
  readableDifference(value:string):string{return String(value||'').replace(/openingVisualPromise/g,'opening visual promise').replace(/characterGoal/g,'character goal').replace(/majorStoryChanges/g,'major story changes').replace(/centralObstacle/g,'central obstacle').replace(/endingFunction/g,'ending function').replace(/mainObjectOrSituation/g,'main object or situation').replace(/escalation/g,'escalation').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/\s+/g,' ').trim();}
