  @HostListener('document:click',['$event']) onDocumentClick(event:MouseEvent){const target=event.target as HTMLElement;if(this.preferencesOpen&&!target.closest('.preference-picker')){this.preferencesOpen=false;this.preferenceQuery='';this.changeDetector.markForCheck();}}
